+    id: filterModel
+
     property /*[{ role: string, value: var }]*/ var filters: []
     property bool filterOutInactiveDevices: false
     property bool filterVirtualDevices: false
+    // Only show the first stream of each application
+    property bool groupByApplication: false

     onFiltersChanged: invalidate()
     onFilterOutInactiveDevicesChanged: invalidate()
     onFilterVirtualDevicesChanged: invalidate()
+    onGroupByApplicationChanged: invalidate()

-    filterRowCallback: function(source_row, source_parent) {
+    // Whether a row is shown depends on the rows before it when grouping
+    readonly property Connections groupConnections: Connections {
+        target: filterModel.groupByApplication ? filterModel.sourceModel : null
+        function onRowsInserted() { Qt.callLater(filterModel.invalidateFilter) }
+        function onRowsRemoved() { Qt.callLater(filterModel.invalidateFilter) }
+        function onRowsMoved() { Qt.callLater(filterModel.invalidateFilter) }
+        function onDataChanged() { Qt.callLater(filterModel.invalidateFilter) }
+    }
+
+    function applicationName(client): string {
+        if (client && client.name && client.name !== "pipewire-media-session") {
+            return client.name;
+        }
+        return "";
+    }
+
+    function acceptsRow(source_row, source_parent): bool {
         const idx = sourceModel.index(source_row, 0, source_parent);

         // Don't ever show the dummy output, that's silly
@@ -50,4 +73,25 @@ KItemModels.KSortFilterProxyModel {

         return true;
     }
+
+    filterRowCallback: function(source_row, source_parent) {
+        if (!acceptsRow(source_row, source_parent)) {
+            return false;
+        }
+
+        if (groupByApplication) {
+            const clientRole = sourceModel.KItemModels.KRoleNames.role("Client");
+            const name = applicationName(sourceModel.data(sourceModel.index(source_row, 0, source_parent), clientRole));
+            if (name) {
+                for (let row = 0; row < source_row; ++row) {
+                    if (applicationName(sourceModel.data(sourceModel.index(row, 0, source_parent), clientRole)) === name
+                        && acceptsRow(row, source_parent)) {
+                        return false;
+                    }
+                }
+            }
+        }
+
+        return true;
+    }
 }
diff --git a/src/qml/listitemmenu.cpp b/src/qml/listitemmenu.cpp
