+QList<QObject *> ListItemMenu::groupedStreams() const
+{
+    QList<QObject *> streams;
+    for (const auto &stream : m_groupedStreams) {
+        if (stream) {
+            streams.append(stream.data());
+        }
+    }
+    return streams;
+}
+
+void ListItemMenu::setGroupedStreams(const QList<QObject *> &groupedStreams)
+{
+    QList<QPointer<PulseAudioQt::Stream>> streams;
+    for (QObject *object : groupedStreams) {
+        if (auto *stream = qobject_cast<PulseAudioQt::Stream *>(object)) {
+            streams.append(stream);
+        }
+    }
+
+    if (m_groupedStreams != streams) {
+        m_groupedStreams = streams;
+        Q_EMIT groupedStreamsChanged();
+    }
+}
+
